def transform(grid):
    """Complete the frame and dense marker rows/columns with color 2."""
    h, w = len(grid), len(grid[0])
    bg = Counter(value for row in grid for value in row).most_common(1)[0][0]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not markers:
        return [row[:] for row in grid]
    r0 = min(r for r, _ in markers)
    r1 = max(r for r, _ in markers)
    c0 = min(c for _, c in markers)
    c1 = max(c for _, c in markers)
    out = [row[:] for row in grid]

    def paint(r, c):
        if grid[r][c] == bg:
            out[r][c] = 2

    # Fill the perimeter of the markers' bounding box.
    for c in range(c0, c1 + 1):
        paint(r0, c)
        paint(r1, c)
    for r in range(r0, r1 + 1):
        paint(r, c0)
        paint(r, c1)

    # Fill additional full-width/full-height marker lines only when they have
    # at least four non-background cells. This preserves sparse two/three-dot
    # rows or columns while completing dense interrupted stripes.
    for r in range(r0 + 1, r1):
        if sum(grid[r][c] != bg for c in range(c0, c1 + 1)) >= 4:
            for c in range(c0, c1 + 1):
                paint(r, c)
    for c in range(c0 + 1, c1):
        if sum(grid[r][c] != bg for r in range(r0, r1 + 1)) >= 4:
            for r in range(r0, r1 + 1):
                paint(r, c)
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
